const companies = $('Get many database pages').all().map(i => i.json);
const meetings = $('Get meetings this week').all().map(i => i.json);

const now = new Date();
const day = now.getDay();
const diffToMonday = (day + 6) % 7;
const startOfWeek = new Date(now);
startOfWeek.setDate(now.getDate() - diffToMonday);
startOfWeek.setHours(0, 0, 0, 0);

const allowedPriorities = new Set(['P0', 'P1', 'P2', 'P3']);

const isThisWeek = (v) => {
  if (!v) return false;
  const d = new Date(v);
  return !Number.isNaN(d.getTime()) && d >= startOfWeek;
};

const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();

const getPriority = (c) => {
  const raw = c.property_Priority ?? c.property_priority ?? c.Priority ?? '';
  return allowedPriorities.has(raw) ? raw : 'P2';
};

const getName = (c) =>
  clean(c.property_Name || c.property_name || c.Name || c.name || 'Unknown Company');

const getWebsite = (c) =>
  clean(c.property_Website || c.property_website || c.Website || c.url || '');

const getNotes = (c) =>
  clean(
    c.property_first_call_notes ||
    c.property_First_call_notes ||
    c.first_call_notes ||
    ''
  );

const getTags = (c) =>
  clean(c.property_Tags || c.property_tags || c.Tags || c.tags || '');

const newCompanies = companies
  .filter(c => isThisWeek(c.property_created_time || c.property_Created_time || c.created_time))
  .map(c => ({
    ...c,
    _priority: getPriority(c),
    _name: getName(c),
    _website: getWebsite(c),
    _notes: getNotes(c),
    _tags: getTags(c),
  }));

const companyById = new Map(companies.map(c => [c.id, c]));
const newCompanyIds = new Set(newCompanies.map(c => c.id));

const getCompanyIdsFromMeeting = (m) => {
  const relA = m.property_company || m.property_Company;
  if (Array.isArray(relA)) {
    return relA.map(x => typeof x === 'string' ? x : x?.id).filter(Boolean);
  }
  const relB = m.properties?.Company?.relation;
  if (Array.isArray(relB)) {
    return relB.map(x => x?.id).filter(Boolean);
  }
  return [];
};

const getMeetingDate = (m) =>
  m.property_call_date?.start ||
  m.property_Call_date?.start ||
  m.property_created_time ||
  m.created_time ||
  m.last_edited_time ||
  '';

const getMeetingNotes = (m) => clean([
  m.property_raw_notes,
  m.property_Raw_notes,
  m.property_raw_notes_2,
  m.property_raw_notes_3,
  m.property_ai_summary,
].filter(Boolean).join(' '));

const updatesByCompany = new Map();

for (const m of meetings) {
  const when = getMeetingDate(m);
  if (!isThisWeek(when)) continue;

  const companyIds = getCompanyIdsFromMeeting(m);
  for (const companyId of companyIds) {
    if (newCompanyIds.has(companyId)) continue;

    const company = companyById.get(companyId);
    const companyName = clean(company ? getName(company) : 'Unknown Company');

    const current = updatesByCompany.get(companyId) || {
      company_id: companyId,
      company_name: companyName,
      company_website: company ? getWebsite(company) : '',
      company_notion_url: clean(company?.url || ''),
      meeting_count: 0,
      latest_meeting_date: '',
      latest_priority: '',
      latest_recommendation: '',
      latest_next_step: '',
      latest_notes_excerpt: '',
    };

    current.meeting_count += 1;

    const prev = current.latest_meeting_date ? new Date(current.latest_meeting_date) : null;
    const curr = when ? new Date(when) : null;
    const isNewer = curr && (!prev || curr > prev);

    if (isNewer) {
      current.latest_meeting_date = when;
      current.latest_priority = clean(
        m.property_priority || m.property_Priority ||
        m.properties?.Priority?.select?.name || ''
      );
      current.latest_recommendation = clean(
        m.property_recommendation || m.property_Recommendation ||
        m.properties?.Recommendation?.select?.name || ''
      );
      current.latest_next_step = clean(m.property_next_step || m.property_Next_step || '');
      current.latest_notes_excerpt = getMeetingNotes(m).slice(0, 1200);
    }

    updatesByCompany.set(companyId, current);
  }
}

const meeting_updates = Array.from(updatesByCompany.values()).sort((a, b) =>
  new Date(b.latest_meeting_date || 0) - new Date(a.latest_meeting_date || 0)
);

return [{
  json: {
    entries: newCompanies,
    meeting_updates,
  }
}];

const input = $input.first().json;
const { entries, meeting_updates } = input;

const allowedPriorities = new Set(['P0', 'P1', 'P2', 'P3']);

const buckets = {
  P0: entries.filter(e => e._priority === 'P0'),
  P1: entries.filter(e => e._priority === 'P1'),
  P2: entries.filter(e => e._priority === 'P2'),
  P3: entries.filter(e => e._priority === 'P3'),
};

const sessionId = Date.now().toString();

// Shared inline styles (injected into each section prompt so each agent call is self-contained)
const tableStyles = `width:100%; border-collapse:collapse; margin-bottom:24px`;
const thStyles = `background:#f0f0f0; padding:8px; border:1px solid #ccc; text-align:left`;
const tdStyles = `padding:8px; border:1px solid #ccc; vertical-align:top`;
const cardStyles = `border:1px solid #ddd; border-radius:4px; padding:16px; margin-bottom:20px; background:#fafafa`;
const h2Styles = `border-bottom:2px solid #333; padding-bottom:6px; margin-top:32px`;
const h3Styles = `color:#1a73e8; margin-top:28px`;

// ── SECTION A: meeting updates for existing companies ──────────────────────────
const sectionAPrompt = `You are generating one section of a weekly VC recap email.
Output ONLY a valid HTML fragment for Section A — no <html>/<body> tags, no markdown, no code fences.

DATA:
${JSON.stringify(meeting_updates)}

INSTRUCTIONS:
1. Open with: <h2 style="${h2Styles}">Existing Companies With New Meetings This Week</h2>
2. If DATA is an empty array: <p>No follow-up meetings this week.</p> — stop.
3. Otherwise render a table (style="${tableStyles}") with columns: Company | New Meetings | Latest Meeting | Update
   - <th style="${thStyles}"> for headers
   - <td style="${tdStyles}"> for cells
   - Company: hyperlink company_name to company_website if non-empty, else to company_notion_url
   - New Meetings: the integer meeting_count
   - Latest Meeting: latest_meeting_date formatted as "MMM D, YYYY" only — no time, no timezone
   - Update: 2-3 clean prose sentences summarising the company and the key takeaway. Draw from latest_notes_excerpt but rewrite — no raw notes, no bullets.
4. All note text is in markdown. Convert to HTML: ## headings → bold label or ignore; - bullets → <li> inside <ul>; never render ##, -, * as literal characters. Strip any line that is a Granola transcript URL.
5. Return the HTML fragment only.`;

// ── SECTION B Part 1: P0 and P1 (detailed cards) ──────────────────────────────
const sectionBP0P1Prompt = `You are generating one section of a weekly VC recap email.
Output ONLY a valid HTML fragment for the P0 and P1 sub-sections — no <html>/<body> tags, no markdown, no code fences.

DATA:
P0=${JSON.stringify(buckets.P0)}
P1=${JSON.stringify(buckets.P1)}

Field names in each record: _name, _notes, _tags, _website

INSTRUCTIONS:
1. Open with: <h2 style="${h2Styles}">New Companies Created This Week</h2>
2. Then: <h3 style="${h3Styles}">P0 – High Conviction / High Thesis Fit</h3>
   - If P0 is empty: <p>No new companies in this category this week.</p>
   - Else for each company render a card div (style="${cardStyles}"):
     a. <h4 style="margin-bottom:4px"><a href="{_website}">{_name}</a></h4> (omit href if _website blank)
     b. <p><strong>Overview</strong></p> then a 3-4 sentence prose paragraph synthesised from _notes. No markdown characters.
     c. <ul style="margin-top:4px; padding-left:20px"> with 3-5 <li style="margin-bottom:4px"> covering Team, Product, Traction, Funding — pulled from _notes, written as clean English phrases.
3. Then: <h3 style="${h3Styles}">P1 – Strong Companies</h3> — exact same card format as P0.
4. CRITICAL: Do NOT move or reclassify any company. Render each company exactly where it appears in P0 or P1.
5. All note text is in markdown. Convert to HTML. Strip Granola transcript URL lines. Never render ##, -, * as literal characters.
6. Return the HTML fragment only.`;

// ── SECTION B Part 2: P2 and P3 (table rows, much shorter) ───────────────────
const sectionBP2P3Prompt = `You are generating one section of a weekly VC recap email.
Output ONLY a valid HTML fragment for the P2 and P3 sub-sections — no <html>/<body> tags, no markdown, no code fences.

DATA:
P2=${JSON.stringify(buckets.P2)}
P3=${JSON.stringify(buckets.P3)}

Field names in each record: _name, _notes, _tags, _website

INSTRUCTIONS:
1. <h3 style="${h3Styles}">Low Conviction (P2)</h3>
   - If P2 is empty: <p>No new companies in this category this week.</p>
   - Else table (style="${tableStyles}") with columns: Company Name | Overview
     - Company Name: hyperlink _name to _website if non-empty
     - Overview: max 2 clean prose sentences drawn from _notes. No markdown.
2. <h3 style="${h3Styles}">Companies met, not worth pursuing (P3)</h3>
   - If P3 is empty: <p>No new companies in this category this week.</p>
   - Else table (style="${tableStyles}") with columns: Company Name | Overview | Tags
     - Company Name: hyperlink _name to _website if non-empty
     - Overview: 1-2 clean prose sentences from _notes. No markdown.
     - Tags: _tags as plain comma-separated text
3. CRITICAL: Do NOT move or reclassify any company.
4. All note text is in markdown. Convert to HTML. Strip Granola transcript URL lines. Never render ##, -, * as literal characters.
5. Table headers: <th style="${thStyles}">, cells: <td style="${tdStyles}">
6. Return the HTML fragment only.`;

return [
  { json: { sessionId, section: 'A',      section_prompt: sectionAPrompt } },
  { json: { sessionId, section: 'B_P0P1', section_prompt: sectionBP0P1Prompt } },
  { json: { sessionId, section: 'B_P2P3', section_prompt: sectionBP2P3Prompt } },
];

// Items arrive as a single aggregated array from the Aggregate node.
// Each item has: { section, sessionId, section_prompt, output }
const items = $input.first().json.data;

// Ensure correct reading order regardless of execution order
const order = ['A', 'B_P0P1', 'B_P2P3'];
items.sort((a, b) => order.indexOf(a.section) - order.indexOf(b.section));

const body = items
  .map(i => (i.output || '').trim())
  .filter(Boolean)
  .join('\n');

const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:700px;margin:auto;padding:20px;">
${body}
</div>`;

return [{ json: { output: html } }];
